# A single-use authorization code (generated by maquina:oauth). Only the
# SHA-256 digest is stored; the raw code exists in the redirect that hands it
# to the client and nowhere else.
class OauthAuthorizationCode < ApplicationRecord
  TTL = 10.minutes
  # RFC 7636: 43-128 characters from the unreserved set.
  VERIFIER = /\A[A-Za-z0-9\-._~]{43,128}\z/

  # One error for every way a redemption fails, so a caller learns nothing
  # about which check it missed.
  class InvalidGrant < StandardError; end

  belongs_to :user
  belongs_to :oauth_client

  scope :unused, -> { where(used_at: nil) }

  # The raw code, returned once.
  def self.issue!(user:, client:, redirect_uri:, code_challenge:, scope:, resource:)
    raw = SecureRandom.urlsafe_base64(32)
    create!(user: user, oauth_client: client, code_digest: AccessToken.digest(raw), code_challenge: code_challenge,
      redirect_uri: redirect_uri, scope: scope, resource: resource, expires_at: TTL.from_now)
    raw
  end

  # The code, now spent. Raises InvalidGrant unless it is known, unexpired,
  # unused, issued to this client for this exact redirect_uri, and the
  # verifier hashes to its PKCE challenge.
  def self.redeem!(raw, client:, redirect_uri:, verifier:)
    code = find_by(code_digest: AccessToken.digest(raw))
    raise InvalidGrant unless code&.redeemable?(client: client, redirect_uri: redirect_uri, verifier: verifier)
    # Claimed in one statement, so two requests racing with the same code get
    # one success between them.
    raise InvalidGrant unless unused.where(id: code.id).update_all(used_at: Time.current) == 1

    code
  end

  def redeemable?(client:, redirect_uri:, verifier:)
    used_at.nil? && expires_at.future? && oauth_client == client && !user.blocked? &&
      redirect_uri.to_s == self.redirect_uri && verifier_matches?(verifier)
  end

  private

  def verifier_matches?(verifier)
    return false unless verifier.to_s.match?(VERIFIER)

    challenge = Base64.urlsafe_encode64(Digest::SHA256.digest(verifier), padding: false)
    ActiveSupport::SecurityUtils.secure_compare(challenge, code_challenge)
  end
end
